INSERT INTO `counseling_topics` VALUES (1,'Akademik & Skripsi','akademik-skripsi','Akademik','Prokrastinasi, kebuntuan menyusun tugas akhir, motivasi belajar turun, atau kesulitan bimbingan.','GraduationCap',1,1,'2026-09-12 20:26:13','2026-09-12 20:26:13'),(2,'Kecemasan & Overthinking','kecemasan-overthinking','Emosi','Pikiran cemas berlebihan tentang masa depan, panic attack, overthinking, atau insomnia.','Brain',1,2,'2026-09-12 20:26:13','2026-09-12 20:26:13'),(3,'Stres Perkuliahan & Burnout','stres-burnout','Kesehatan Mental','Kelelahan emosional akibat beban tugas, organisasi, dan tuntutan akademik yang menumpuk.','Sparkles',1,3,'2026-09-12 20:26:13','2026-09-12 20:26:13'),(4,'Relasi Pertemanan & Sosial','relasi-sosial','Sosial','Konflik dengan teman satu angkatan, kesepian di perantauan, atau adaptasi lingkungan baru.','Users',1,4,'2026-09-12 20:26:13','2026-09-12 20:26:13'),(5,'Keluarga & Ekonomi','keluarga-ekonomi','Keluarga','Dilema ekspektasi orang tua, konflik internal keluarga, atau kecemasan finansial kuliah.','Home',1,5,'2026-09-12 20:26:13','2026-09-12 20:26:13'),(6,'Arah Karier & Masa Depan','arah-karier-masa-depan','Karier','Bingung menentukan peminatan, magang, persiapan karier profesional, atau krisis quarter-life.','Compass',1,6,'2026-09-12 20:26:13','2026-09-12 20:26:13');
/*!40000 ALTER TABLE `counseling_topics` ENABLE KEYS */;
UNLOCK TABLES;

