INSERT INTO `nara_voice_recordings` VALUES (1,'counseling_step_0','Pengajuan Konseling','Langkah 0: Sapaan Awal Nara','Halo! Saya Nara, asisten virtual Anda. Yuk luangkan 2-3 menit menjawab 5 pertanyaan santai ini agar konselor mengenal situasimu dengan baik.','Dibacakan pertama kali saat mahasiswa membuka formulir asesmen awal.','voice_recordings/counseling_step_0_test.mp3',6,'audio/mpeg',19584,1,1,1,'2026-09-13 00:30:20','2026-09-13 00:34:22'),(2,'counseling_step_1','Pengajuan Konseling','Pertanyaan 1: Kendala Utama','Pilih satu kendala yang paling menyita energimu saat ini. Jika belum ada di daftar pilihan, kamu juga bisa memilih opsi Lainnya.','Panduan saat mahasiswa memilih kendala utama terkait topik yang dihadapi.',NULL,NULL,NULL,NULL,NULL,1,2,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(3,'counseling_step_2','Pengajuan Konseling','Pertanyaan 2: Durasi Kondisi','Kira-kira sudah berapa lama kamu merasakan kondisi ini? Informasi durasi penting agar konselor memahami perjalanan kondisimu.','Panduan saat mahasiswa ditanya berapa lama merasakan kondisi tersebut.',NULL,NULL,NULL,NULL,NULL,1,3,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(4,'counseling_step_3','Pengajuan Konseling','Pertanyaan 3: Tingkat Dampak Harian','Seberapa besar kondisi ini memengaruhi fokus kuliah atau kegiatan harianmu? Pilih skala 1 (Sangat Ringan) sampai 5 (Sangat Mengganggu).','Panduan saat mahasiswa menilai skala dampak 1 sampai 5.',NULL,NULL,NULL,NULL,NULL,1,4,'2026-09-13 00:30:20','2026-09-13 00:54:12'),(5,'counseling_step_4','Pengajuan Konseling','Pertanyaan 4: Upaya Mandiri Sebelumnya','Apakah ada cara atau upaya mandiri yang pernah kamu coba sebelumnya? Ceritakan apa saja, konselor siap mendengarkan.','Panduan saat mahasiswa menceritakan apa yang sudah pernah dicoba.',NULL,NULL,NULL,NULL,NULL,1,5,'2026-09-13 00:30:20','2026-09-13 00:54:12'),(6,'counseling_step_5','Pengajuan Konseling','Pertanyaan 5: Harapan Terhadap Konseling','Tuliskan hal utama atau harapan yang paling ingin kamu sampaikan langsung ke konselor. Ceritamu aman dan dijamin kerahasiaannya.','Panduan saat mahasiswa menuliskan harapan atau cerita utama.',NULL,NULL,NULL,NULL,NULL,1,6,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(7,'counseling_step_6','Pengajuan Konseling','Langkah 6: Rangkuman & Konfirmasi','Semua jawabanmu sudah lengkap! Periksa kembali rangkuman di samping. Jika sudah sesuai, kita lanjut ke pemilihan jadwal konseling.','Dibacakan saat seluruh pertanyaan selesai dijawab sebelum memilih jadwal.',NULL,NULL,NULL,NULL,NULL,1,7,'2026-09-13 00:30:20','2026-09-13 00:54:12'),(8,'poke_1','Sapaan & Interaksi','Respon Sentuh 1: Nara Siap Membantu','Halo! Nara siap bantu jika ada pertanyaan yang membingungkan.','Diputar saat pengguna mengklik atau menyapa avatar Nara.',NULL,NULL,NULL,NULL,NULL,1,8,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(9,'poke_2','Sapaan & Interaksi','Respon Sentuh 2: Cerita Aman & Privat','Jawab dengan santai ya, ceritamu aman dan privat bersama konselor.','Pesan penguatan privasi mahasiswa.',NULL,NULL,NULL,NULL,NULL,1,9,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(10,'poke_3','Sapaan & Interaksi','Respon Sentuh 3: Apresiasi Langkah Awal','Kamu hebat sudah mengambil langkah pertama untuk konseling!','Pesan afirmasi positif untuk keberanian mahasiswa.',NULL,NULL,NULL,NULL,NULL,1,10,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(11,'poke_4','Sapaan & Interaksi','Respon Sentuh 4: Ajakan Melihat Tips','Butuh panduan lebih dalam? Klik tombol Tips di atas ya.','Mengarahkan mahasiswa melihat tips pengisian.',NULL,NULL,NULL,NULL,NULL,1,11,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(12,'general_greeting','Sapaan & Interaksi','Sapaan Umum Ruang BK','Saya Nara, asisten virtual Anda di Ruang BK.','Sapaan singkat default Nara di berbagai sudut aplikasi.',NULL,NULL,NULL,NULL,NULL,1,12,'2026-09-13 00:30:20','2026-09-13 00:30:20'),(13,'screening_intro','Skrining Mandiri','Pengantar Skrining Kesehatan Mental','Selamat datang di asesmen kesehatan mental. Jawablah setiap pernyataan sesuai apa yang kamu rasakan selama 2 minggu terakhir dengan santai dan jujur.','Dibacakan saat mahasiswa membuka tes kuesioner skrining 20 soal.',NULL,NULL,NULL,NULL,NULL,1,13,'2026-09-13 00:30:21','2026-09-13 00:30:21');
/*!40000 ALTER TABLE `nara_voice_recordings` ENABLE KEYS */;
UNLOCK TABLES;

