INSERT INTO `questionnaires` VALUES (1,'Screening Kebutuhan Bimbingan & Konseling (Komprehensif)','Instrumen evaluasi mandiri untuk memetakan kebutuhan dukungan akademik, emosional, sosial, dan perencanaan karier.','Pilihlah respon yang paling mencerminkan kondisi Anda dalam 2–4 minggu terakhir. Tidak ada jawaban yang salah atau benar.','published','1.0','2026-09-12 20:26:14','2026-09-12 20:26:14'),(2,'Screening Kesiapan Karier & Masa Depan','Evaluasi terarah mengenai perencanaan karier, eksplorasi peluang magang/kerja, serta kesiapan profesional.','Jawablah setiap pertanyaan sesuai keyakinan diri Anda saat ini.','draft','1.0','2026-09-12 20:26:14','2026-09-12 20:26:14'),(3,'Check-in Adaptasi Mahasiswa Baru','Pemetaan transisi belajar, adaptasi pertemanan, dan manajemen kemandirian.','Khusus bagi mahasiswa baru yang sedang menjalani semester awal.','draft','1.0','2026-09-12 20:26:14','2026-09-12 20:26:14');
