INSERT INTO `questions` VALUES (1,1,'Akademik','Saya merasa kewalahan dengan beban tugas atau tuntutan perkuliahan.','likert',1,0,0,1,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(2,1,'Akademik','Saya kesulitan berkonsentrasi atau mempertahankan fokus saat belajar.','likert',1,0,0,2,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(3,1,'Akademik','Saya merasa motivasi belajar saya menurun signifikan akhir-akhir ini.','likert',1,0,0,3,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(4,1,'Emosi / Stres','Saya sering merasa cemas, gelisah, atau tegang tanpa alasan yang pasti.','likert',1,0,0,4,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(5,1,'Emosi / Stres','Saya merasa sulit beristirahat atau mengalami gangguan tidur karena beban pikiran.','likert',1,0,0,5,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(6,1,'Emosi / Stres','Saya merasa putus asa atau merasa tidak ada jalan keluar dari permasalahan saya.','likert',1,0,1,6,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(7,1,'Sosial','Saya merasa memiliki seseorang yang nyaman untuk diajak bercerita secara terbuka.','likert',1,1,0,7,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(8,1,'Sosial','Saya merasa terisolasi atau kesulitan menjalin pertemanan di lingkungan sekitar.','likert',1,0,0,8,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(9,1,'Sosial','Saya merasa cemas atau tidak nyaman saat harus berinteraksi dalam kelompok.','likert',1,0,0,9,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(10,1,'Keluarga dan Ekonomi','Saya merasa masalah atau dinamika keluarga memengaruhi konsentrasi aktivitas saya.','likert',1,0,0,10,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(11,1,'Keluarga dan Ekonomi','Kondisi ekonomi atau biaya hidup menjadi beban pikiran utama bagi saya.','likert',1,0,0,11,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(12,1,'Keluarga dan Ekonomi','Tuntutan atau ekspektasi keluarga membuat saya merasa tertekan.','likert',1,0,0,12,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(13,1,'Karier dan Masa Depan','Saya merasa bingung menentukan arah peminatan atau tujuan setelah lulus.','likert',1,0,0,13,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(14,1,'Karier dan Masa Depan','Saya merasa cemas apakah keahlian saya relevan dengan tuntutan dunia kerja.','likert',1,0,0,14,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(15,1,'Karier dan Masa Depan','Saya memiliki gambaran yang jelas mengenai langkah karier yang ingin saya capai.','likert',1,1,0,15,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(16,1,'Kebutuhan Dukungan','Saya merasa memerlukan bimbingan rutin dari seorang konselor profesional.','likert',1,0,0,16,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(17,1,'Kebutuhan Dukungan','Saya merasa terbantu ketika memiliki sesi evaluasi dan target mingguan.','likert',1,0,0,17,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(18,1,'Kebutuhan Dukungan','Saya merasa pikiran untuk menyakiti diri sendiri pernah terlintas saat tertekan.','likert',1,0,1,18,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(19,1,'Kebutuhan Dukungan','Ceritakan secara singkat hal yang paling mengganggu pikiran atau aktivitas kuliah Anda saat ini.','textarea',0,0,0,19,'2026-09-12 20:26:14','2026-09-12 20:26:14'),(20,1,'Kebutuhan Dukungan','Apa harapan atau bantuan utama yang Anda inginkan dari layanan konseling Ruang BK?','textarea',0,0,0,20,'2026-09-12 20:26:14','2026-09-12 20:26:14');
